// Regenerates PROGRESS.md from lib/kapital.ts, the single source of chapter status.
// Run with: npm run progress
import { writeFileSync } from "node:fs";
import { VOLUMES } from "../lib/kapital.ts";

const lines = [
  "# Progress",
  "",
  "Generated by `npm run progress` from `lib/kapital.ts`. Do not edit by hand.",
  "",
  "- [x] Phase 1 shell: home page, chapter template, animation player, glossary, introduction",
  "",
];
for (const v of VOLUMES) {
  const done = v.chapters.filter((c) => c.status === "ready").length;
  lines.push(`## ${v.label}: ${v.title} (${done}/${v.chapters.length})`, "");
  for (const p of v.parts) {
    lines.push(v.kind === "prelude" ? `**${p.title}**` : `**Part ${p.n}${v.kind === "bonus" ? "" : `: ${p.title}`}**`, "");
    for (const c of v.chapters.filter((c) => c.n >= p.chapters[0] && c.n <= p.chapters[1])) {
      lines.push(`- [${c.status === "ready" ? "x" : " "}] ${c.n}. ${c.title}`);
    }
    lines.push("");
  }
}
lines.push("## Phase 5 extras", "", "- [x] The whole story in one animation (wrap-up chapter, /the-whole-story)", "- [x] Cross-volume glossary review (search, volume filters, \"also in\" and \"see also\" links)", "");
writeFileSync(new URL("../PROGRESS.md", import.meta.url), lines.join("\n"));
console.log("PROGRESS.md written");
